CREATE TYPE "Category" AS ENUM ('HEALTH','MENTAL','SELF_CARE','NUTRITION');
CREATE TYPE "TaskType" AS ENUM ('STATIC','PROGRESSIVE');
CREATE TYPE "Unit" AS ENUM ('REPS','MINUTES','KM','PAGES','CUSTOM');
CREATE TYPE "Difficulty" AS ENUM ('EASY','MEDIUM','HARD');
CREATE TYPE "Rarity" AS ENUM ('COMMON','RARE','LEGENDARY','SEASONAL');
CREATE TABLE "Palette" ("id" TEXT PRIMARY KEY,"order" INTEGER NOT NULL UNIQUE,"name" TEXT NOT NULL,"rarity" "Rarity" NOT NULL,"colors" JSONB NOT NULL,"isSeasonal" BOOLEAN NOT NULL DEFAULT false,"seasonStart" TIMESTAMP(3),"seasonEnd" TIMESTAMP(3),"unlockLevel" INTEGER,"requiresPrestige" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"displayName" TEXT NOT NULL,"timezone" TEXT NOT NULL DEFAULT 'UTC',"level" INTEGER NOT NULL DEFAULT 1,"totalExp" INTEGER NOT NULL DEFAULT 0,"lifetimeExp" INTEGER NOT NULL DEFAULT 0,"prestigeCount" INTEGER NOT NULL DEFAULT 0,"activePaletteId" TEXT,"darkMode" BOOLEAN NOT NULL DEFAULT false,"leaderboardOptIn" BOOLEAN NOT NULL DEFAULT false,"leaderboardNickname" TEXT,"shareSlug" TEXT NOT NULL UNIQUE,"publicProfile" BOOLEAN NOT NULL DEFAULT false,"expVaultBalance" INTEGER NOT NULL DEFAULT 0,"onboardingCompletedAt" TIMESTAMP(3),"hasCompletedFirstDay" BOOLEAN NOT NULL DEFAULT false,"lastWeeklyRecapKey" TEXT,"lastWelcomeBackAt" TIMESTAMP(3),"lastCompletionAt" TIMESTAMP(3),"lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_activePaletteId_fkey" FOREIGN KEY ("activePaletteId") REFERENCES "Palette"("id") ON DELETE SET NULL);
CREATE TABLE "Task" ("id" TEXT PRIMARY KEY,"category" "Category" NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"icon" TEXT NOT NULL,"type" "TaskType" NOT NULL,"baseExp" INTEGER NOT NULL,"baseTarget" INTEGER,"scalingFactor" DOUBLE PRECISION,"unit" "Unit","difficultyTag" "Difficulty" NOT NULL,"whyThisHabit" TEXT NOT NULL,"isStarterTask" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "UserTask" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"addedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"isPaused" BOOLEAN NOT NULL DEFAULT false,"personalTargetOverride" INTEGER,"iconOverride" TEXT,"unitOverride" "Unit","currentTarget" INTEGER,"consecutiveMisses" INTEGER NOT NULL DEFAULT 0,"targetRegressionLog" JSONB NOT NULL DEFAULT '[]',UNIQUE("userId","taskId"),FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("taskId") REFERENCES "Task"("id") ON DELETE CASCADE);
CREATE TABLE "DailyLog" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"date" TIMESTAMP(3) NOT NULL,"expEarned" INTEGER NOT NULL,"targetAtCompletion" INTEGER,"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("userId","taskId","date"),FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("taskId") REFERENCES "Task"("id") ON DELETE CASCADE);
CREATE TABLE "UserPalette" ("userId" TEXT NOT NULL,"paletteId" TEXT NOT NULL,"unlockedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("userId","paletteId"),FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("paletteId") REFERENCES "Palette"("id") ON DELETE CASCADE);
CREATE TABLE "Badge" ("id" TEXT PRIMARY KEY,"key" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"icon" TEXT NOT NULL);
CREATE TABLE "UserBadge" ("userId" TEXT NOT NULL,"badgeId" TEXT NOT NULL,"earnedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("userId","badgeId"),FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE,FOREIGN KEY("badgeId") REFERENCES "Badge"("id") ON DELETE CASCADE);
CREATE TABLE "HabitStack" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"description" TEXT NOT NULL);
CREATE TABLE "HabitStackTask" ("stackId" TEXT NOT NULL,"taskId" TEXT NOT NULL,PRIMARY KEY("stackId","taskId"),FOREIGN KEY("stackId") REFERENCES "HabitStack"("id") ON DELETE CASCADE,FOREIGN KEY("taskId") REFERENCES "Task"("id") ON DELETE CASCADE);
